"""Pytest suite for days_in_month(year, month), derived from SMT/CSP-backed
test-generation covering leap-year equivalence classes, month/array boundary
values, general equivalence-class representatives, and robustness/counterexample
checks on the unvalidated `month` input.
"""
import pytest

from target import days_in_month


# --- Group 1: Leap-year equivalence classes / century boundaries ---------
# Each verified via SMT goal: And(year % 4 == 0, Or(year % 100 != 0, year % 400 == 0))

def test_leap_div_by_400_year_2000():
    # SMT-proved: 2000 % 400 == 0 -> leap (div-by-400 class)
    assert days_in_month(2000, 2) == 29


def test_leap_div_by_400_year_2400():
    # SMT-proved: second representative of div-by-400 class
    assert days_in_month(2400, 2) == 29


def test_not_leap_div_by_100_not_400_year_1900():
    # SMT-refuted leap goal: 1900 div by 100, not by 400 -> not leap; century boundary
    assert days_in_month(1900, 2) == 28


def test_not_leap_div_by_100_not_400_year_2100():
    # SMT-refuted leap goal: 2100 div by 100, not by 400 -> not leap; century boundary
    assert days_in_month(2100, 2) == 28


def test_not_leap_year_100():
    # Smallest positive div-by-100-not-by-400 year -> not leap
    assert days_in_month(100, 2) == 28


def test_not_leap_year_200():
    # div by 100, not by 400 -> not leap
    assert days_in_month(200, 2) == 28


def test_not_leap_year_300():
    # div by 100, not by 400 -> not leap
    assert days_in_month(300, 2) == 28


def test_leap_year_400():
    # Smallest positive div-by-400 year -> leap
    assert days_in_month(400, 2) == 29


def test_leap_ordinary_year_2024():
    # Ordinary div-by-4-not-100 leap year
    assert days_in_month(2024, 2) == 29


def test_not_leap_ordinary_year_2023():
    # Adjacent non-leap year (not div by 4); also a counterexample check:
    # a non-multiple-of-4 year in February must never return 29
    assert days_in_month(2023, 2) == 28


def test_leap_year_1996():
    # Pre-2000 ordinary leap year
    assert days_in_month(1996, 2) == 29


def test_not_leap_year_1999_near_century():
    # One year before the 2000 century boundary
    assert days_in_month(1999, 2) == 28


def test_not_leap_year_2001_near_century():
    # One year after the 2000 century boundary
    assert days_in_month(2001, 2) == 28


def test_leap_year_96_adjacent_below_century():
    # div by 4, not by 100, adjacent below the 100-boundary
    assert days_in_month(96, 2) == 29


def test_leap_year_104_adjacent_above_century():
    # div by 4, not by 100, adjacent above the 100-boundary
    assert days_in_month(104, 2) == 29


def test_leap_smallest_positive_year_4():
    # SMT-proved smallest positive leap year (Not(leap) proved for y in [1,3])
    assert days_in_month(4, 2) == 29


def test_leap_year_8():
    # Next div-by-4 year after 4
    assert days_in_month(8, 2) == 29


def test_not_leap_smallest_positive_non_div4_year_1():
    # Smallest positive non-div-by-4 year
    assert days_in_month(1, 2) == 28


def test_leap_formula_year_0_edge_case():
    # year=0: 0 % 4 == 0 % 100 == 0 % 400 == 0 -> leap by formula;
    # documents behavior at a domain edge not explicitly excluded by the docstring
    assert days_in_month(0, 2) == 29


def test_leap_formula_negative_year_edge_case():
    # Python modulo on negatives: -4 % 4 == 0, -4 % 100 == 96 != 0 -> leap by formula;
    # documents lack of domain validation for year
    assert days_in_month(-4, 2) == 29


# --- Group 2: Month / array-index boundaries (year fixed to non-leap 2023) -

def test_month_lower_array_boundary_january():
    # SMT-proved index boundary: month=1 -> index 0
    assert days_in_month(2023, 1) == 31


def test_month_upper_array_boundary_december():
    # SMT-proved index boundary: month=12 -> index 11
    assert days_in_month(2023, 12) == 31


def test_month_31_day_adjacent_to_february_march():
    # 31-day month adjacent to February
    assert days_in_month(2023, 3) == 31


def test_month_transition_march_to_april():
    # Boundary transition: Mar(31) -> Apr(30)
    assert days_in_month(2023, 4) == 30


def test_month_30_day_adjacent_transition_september():
    # 30-day month adjacent to a transition
    assert days_in_month(2023, 9) == 30


def test_month_transition_september_to_october():
    # Boundary transition: Sep(30) -> Oct(31)
    assert days_in_month(2023, 10) == 31


# --- Group 3: General equivalence-class representatives (CSP-confirmed) ---
# Disjoint partition of months 1..12 into {31-day}, {30-day}, {Feb}

def test_equivalence_class_31_day_month_representative():
    # Non-boundary representative of the 31-day class
    assert days_in_month(2023, 7) == 31


def test_equivalence_class_30_day_month_representative():
    # Non-boundary representative of the 30-day class
    assert days_in_month(2023, 6) == 30


# --- Group 4: Robustness / no-validation gap (documents current behavior) --

def test_month_zero_wraps_to_december_value():
    # Python negative-index wraparound: month=0 -> index -1 -> MONTH_DAYS[-1] == MONTH_DAYS[11];
    # function silently accepts invalid month=0 instead of raising, per manual reasoning
    # about MONTH_DAYS indexing (not modeled by SMT, which treats month as unbounded int)
    assert days_in_month(2023, 0) == 31


def test_month_thirteen_raises_index_error():
    # month=13 -> index 12, out of range for the 12-element MONTH_DAYS list;
    # uncontrolled IndexError since there is no explicit validation
    with pytest.raises(IndexError):
        days_in_month(2023, 13)
